toolArgs.file_text:
@page "/settings"
@using sv_a7365959879c4e938b9bf2d6225d052c.Components.Pages.Settings

@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    color: #555;
    font-weight: 500;
    transition: all 0.2s;
    border-left: 3px solid transparent;
}

.settings-nav-item:hover {
    background: #e9ecef;
    color: #333;
}

.settings-nav-item.active {
    background: #e3f2fd;
    color: #1976d2;
    border-left-color: #1976d2;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.2rem;
}

/* Content Area */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    max-width: 800px;
}

.settings-section h2 {
    margin-bottom: 1.5rem;
    color: #333;
    font-size: 1.5rem;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.5rem;
    color: #444;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-control:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.15);
}

textarea.form-control {
    resize: vertical;
}

/* Buttons */
.btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: #1976d2;
    color: #fff;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #333;
}

.btn-secondary:hover {
    background: #bdbdbd;
}

.btn-danger {
    background: #d32f2f;
    color: #fff;
}

.btn-danger:hover {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

/* Toast */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    font-weight: 500;
    animation: slideIn 0.3s ease;
}

.toast-success {
    background: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

/* Avatar */
.avatar-preview {
    margin-bottom: 1.5rem;
    text-align: center;
}

.avatar-image {
    width: 96px;
    height: 96px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #e0e0e0;
}

.avatar-url-label {
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.5rem;
}

/* Toggles */
.toggle-group {
    margin-bottom: 1rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    cursor: pointer;
    font-weight: 500;
    color: #444;
}

.toggle-input {
    width: 18px;
    height: 18px;
    accent-color: #1976d2;
}

/* Channels */
.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
    margin-bottom: 1rem;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0.6rem;
    background: #f5f5f5;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
}

/* Expandable Panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1rem 1.25rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-weight: 600;
    font-size: 1rem;
    color: #333;
}

.panel-header:hover {
    background: #e9ecef;
}

.panel-body {
    padding: 1.25rem;
    border-top: 1px solid #e0e0e0;
}

/* TFA */
.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 1rem;
}

.status-indicator {
    font-weight: 500;
}

.status-on {
    color: #2e7d32;
}

.status-off {
    color: #888;
}

.last-changed {
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

.sessions-table th,
.sessions-table td {
    text-align: left;
    padding: 0.6rem 0.75rem;
    border-bottom: 1px solid #eee;
}

.sessions-table th {
    font-weight: 600;
    color: #555;
    background: #f8f9fa;
}

.current-session-badge {
    font-size: 0.8rem;
    padding: 0.2rem 0.5rem;
    background: #e3f2fd;
    color: #1976d2;
    border-radius: 4px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin-bottom: 0.75rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
    justify-content: flex-end;
}

/* Radio Groups */
.radio-group {
    display: flex;
    gap: 1.5rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
}

/* Appearance Preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed #ccc;
    border-radius: 8px;
    transition: all 0.3s;
}

.preview-area h4 {
    margin-bottom: 0.5rem;
}

.preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid #ddd;
    border-radius: 6px;
}

.preview-theme-light {
    background: #fff;
    color: #333;
}

.preview-theme-dark {
    background: #2d2d2d;
    color: #eee;
    border-color: #555;
}

.preview-theme-dark .preview-card {
    border-color: #555;
    background: #3a3a3a;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* Error message */
.error-message {
    color: #d32f2f;
    font-size: 0.9rem;
    margin-bottom: 0.75rem;
}

.loading {
    color: #888;
    font-style: italic;
}

